\documentclass[tikz,border=10pt]{standalone}
% Scale: s = 0.012882 cm/px, centre (cx,cy) = (367,364) px, y flipped
\begin{document}
\begin{tikzpicture}[line width=1.5pt, line join=round]
  % Named vertices (converted from pixels)
  \coordinate (A) at (1.97,3.43);     % A (519.97,97.84)
  \coordinate (B) at (-3.79,-3.41);   % B (72.56,628.78)
  \coordinate (C) at (3.80,-3.42);    % C (662.12,629.28)
  \coordinate (O) at (1.97,-1.29);    % O (520.17,464.3)
  \coordinate (P) at (2.09,-1.25);    % extension of BO past O
  \coordinate (Q) at (1.76,-1.04);    % extension of CO past O

  % Triangle ABC, no fill
  \draw (A) -- (B) -- (C) -- cycle;

  % Vertical altitude from A to O
  \draw (A) -- (O);

  % Cevians from B and C through O, extended slightly
  \draw (B) -- (P);
  \draw (C) -- (Q);

  % Labels
  \node[above, font=\fontsize{15}{18}\selectfont] at (A) {$A$};
  \node[below left, font=\fontsize{15}{18}\selectfont] at (B) {$B$};
  \node[below right, font=\fontsize{15}{18}\selectfont] at (C) {$C$};
  \node[below left, font=\fontsize{15}{18}\selectfont] at (O) {$O$};
\end{tikzpicture}
\end{document}

